#include <bitset>
#include <limits>
#include <iostream>

using UShortLimits = std::numeric_limits<unsigned short>;

int main() {
    // N is precisely the number of value bits in unsigned short (e.g., 16)
    const int N = UShortLimits::digits;

    std::bitset<N> bs(267); 

    std::cout << "Size (digits): " << N << "\n";
    std::cout << "Binary: " << bs << "\n";

    // Example of truncation if N is too small:
    // If N is 8, 267 (1 0000 1011) becomes 0000 1011 (11)
    std::bitset<8> truncated(267);
    std::cout << "Truncated (8 bits): " << truncated << "\n";
}
